export type DanceKeyBone = { rx: number; rz: number };
export type DanceKeyTorso = { rx: number; ry: number; rz: number; sy: number };
export type DanceKeyHead = { rx: number; rz: number; ry?: number };
export type DanceKeyRoot = { yaw: number; x: number; y: number; z: number };
export type DanceKey = {
  torso: DanceKeyTorso;
  head: DanceKeyHead;
  armL: DanceKeyBone;
  armR: DanceKeyBone;
  legL: DanceKeyBone;
  legR: DanceKeyBone;
  root?: DanceKeyRoot; // R-B-6: 몸 회전·이동(누적 yaw). 없으면 0.
};
export type DanceClip = {
  id: string;
  bpm: number;
  counts: number; // clip length in beats; playback loops every `counts` beats
  keys: DanceKey[]; // key i = clip-beat i*counts/keys.length (v2: 1/4 beat; test: 1/2 beat)
};
